## Why This Is Asked

This question evaluates your ability to design end-to-end tests for complex, privacy-conscious configurations spanning multiple services, data residency requirements, and dynamic rollout strategies.

## Key Concepts
- Feature-flag propagation across 120 microservices via event bus
- Canary vs. percentage-based rollouts and race condition handling
- Per-tenant caches with data residency enforcement
- Cache invalidation and immutable audit logging
- Fault injection: service outages, retry logic, and exponential backoff

## Code Example
```javascript
// Pseudo-test skeleton (using your preferred E2E framework)
async function testFlagRollout() {
  const tenants = await seedTenants([
    { id: 'tenant-1', region: 'us-east' },
    { id: 'tenant-2', region: 'eu-west' },
    { id: 'tenant-3', region: 'ap-south' }
  ]);

  // Test canary rollout (5%)
  await flagService.update({ key: 'new-feature', rollout: 5 });
  await waitForPropagation(60000);

  // Verify canary distribution
  for (const tenant of tenants) {
    const flag = await getFlag(tenant.id, 'new-feature');
    expect(flag.enabled).toBe(tenant.region === 'us-east');
    await verifyAuditLog(tenant.id, 'new-feature', 'canary');
  }

  // Test 50% rollout
  await flagService.update({ key: 'new-feature', rollout: 50 });
  await waitForPropagation(60000);

  // Verify all services observe flag
  const serviceFlags = await collectFromAllServices('new-feature');
  expect(serviceFlags.every(f => f.enabled)).toBe(true);

  // Verify cache invalidation
  for (const tenant of tenants) {
    const cacheStatus = await getCacheStatus(tenant.id);
    expect(cacheStatus.invalidated).toBe(true);
  }
}

// Fault injection: service outage
async function testFlagServiceOutage() {
  await simulateServiceOutage('flag-service');
  await flagService.update({ key: 'fallback-test', rollout: 100 });

  // Verify retries and eventual consistency
  await waitForPropagation(120000);
  const flags = await collectFromAllServices('fallback-test');
  expect(flags.every(f => f.enabled)).toBe(true);
}

// Load test: rapid toggles and race conditions
async function testRapidToggles() {
  const toggles = Array(100).fill().map((_, i) => ({
    key: `feature-${i}`,
    rollout: Math.random() * 100
  }));

  await Promise.all(toggles.map(t => flagService.update(t)));
  await waitForPropagation(60000);

  // Verify consistency under load
  for (const toggle of toggles) {
    const flags = await collectFromAllServices(toggle.key);
    const enabledCount = flags.filter(f => f.enabled).length;
    const expectedCount = Math.floor(120 * (toggle.rollout / 100));
    expect(Math.abs(enabledCount - expectedCount)).toBeLessThan(5);
  }
}
```

